// Texture Filter / Degrade: Suno Studio audio effect for the FX / OTHER stem (applied to rendered audio, not a lyric tag).
// DEGRADE NOTE: the 'degrade' stage is the SAME fixed 8-level amplitude quantizer COPIED from the digital-degrade
// plugin (a sum of 7 g.compareLt step comparators across [-1, 1] mapping every input to one of 8 discrete levels).
// It is a FIXED-DEPTH amplitude quantizer, NOT a variable bit crusher: because the DSP graph is static and no
// runtime rounding / floor / mod primitive is confirmed, the step COUNT cannot vary from a knob. The 'degrade'
// knob only blends how much of that fixed-depth quantized signal is mixed in. See AUTHORING.md.
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Band-limit: g.biquad highpass at 'hp' then g.biquad lowpass at 'lp'.
//   3. Lo-fi tilt EQ: lowshelf +tilt near 250Hz and highshelf -tilt near 5kHz (opposite via g.mul by -1),
//      driven by one 'lofi tilt' param.
//   4. Degrade: fixed 8-level amplitude staircase (copied from digital-degrade) blended by 'degrade' percent.
//   5. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   6. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
// ASSUMPTION: the shelf g.biquad stages pass a 'gainDb' field not confirmed from the one example (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var hp = g.input('hp');
  var lp = g.input('lp');
  var tiltDb = g.input('lofi tilt');
  var degradePct = g.input('degrade');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));
  var dMix = g.clamp(g.div(degradePct, g.constant(100)), g.zero(), g.constant(1));
  var negTilt = g.mul(tiltDb, g.constant(-1));

  // Fixed 8-level quantizer built from a sum of 7 g.compareLt step comparators at evenly spaced thresholds
  // across [-1, 1] (copied from digital-degrade). idx = number of thresholds strictly below x, in 0..7.
  // level = -1 + (idx + 0.5) * (2/8). Distinct inputs in the same band collapse to the SAME output.
  function staircase(x) {
    var c = g.clamp(x, g.constant(-1), g.constant(1));
    var idx = g.add(
      g.add(
        g.add(g.compareLt(g.constant(-0.75), c), g.compareLt(g.constant(-0.5), c)),
        g.add(g.compareLt(g.constant(-0.25), c), g.compareLt(g.constant(0), c))
      ),
      g.add(
        g.add(g.compareLt(g.constant(0.25), c), g.compareLt(g.constant(0.5), c)),
        g.compareLt(g.constant(0.75), c)
      )
    );
    return g.add(g.constant(-1), g.mul(g.add(idx, g.constant(0.5)), g.constant(0.25)));
  }

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var hpf = g.biquad({ input: trimmed, cutoff: hp, resonance: g.constant(0.707), mode: 'highpass' });
    var lpf = g.biquad({ input: hpf, cutoff: lp, resonance: g.constant(0.707), mode: 'lowpass' });
    var low = g.biquad({ input: lpf, cutoff: g.constant(250), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: tiltDb });
    var tilted = g.biquad({ input: low, cutoff: g.constant(5000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: negTilt });
    var quantized = staircase(tilted);
    var degraded = g.lerp(dMix, tilted, quantized);
    var wet = g.lerp(mix, trimmed, degraded);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
